package com.example.starter.model;

import java.time.Instant;

/**
 * 资料核对表行。
 *
 * @param itemCode    目录项编码
 * @param itemName    目录项名称
 * @param required    是否必交
 * @param submitted   是否已提交
 * @param submittedAt 提交时间（UTC），未提交为null
 */
public record DocumentItemRow(
        String itemCode,
        String itemName,
        boolean required,
        boolean submitted,
        Instant submittedAt) {
}

package com.example.starter.model;

import java.math.BigDecimal;

/**
 * 检验链项目行。
 *
 * @param itemCode      检验项目编码
 * @param itemName      检验项目名称
 * @param critical      是否关键项目
 * @param limitValue    限值
 * @param measuredValue 测定值
 * @param qualified     是否合格（测定值小于等于限值，恰等限值判合格）
 */
public record InspectionItemRow(
        String itemCode,
        String itemName,
        boolean critical,
        BigDecimal limitValue,
        BigDecimal measuredValue,
        boolean qualified) {
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 公示记录行。
 *
 * @param processId           关联流程ID
 * @param startAt             公示开始时间（UTC）
 * @param endAt               公示期满时间（UTC，开始后7个自然日）
 * @param status              公示状态：IN_PROGRESS/OBJECTION/EFFECTIVE
 * @param objectionRequestId  异议受理请求ID，无异议为null
 * @param objectionReason     异议理由，无异议为null
 */
public record PublicityRow(
        long processId,
        Instant startAt,
        Instant endAt,
        String status,
        String objectionRequestId,
        String objectionReason) {
}

